"""Writes signs.json: the fingerspelling alphabet, digits and draft ISL word signs, in the gestures.json format.

Every entry is a draft until an ISL reviewer signs it off (content-review-record.md).
    python tools/content/build_signs.py && python tools/content/build_content.py --manifest-only
"""
import json
import pathlib

SIGNS_FILE = pathlib.Path(__file__).resolve().parents[2] / "app" / "src" / "main" / "assets" / "content" / "signs.json"
NOTE = (
    "Generated by tools/content/build_signs.py; edit the script, not this file. Draft: the ISL alphabet follows the "
    "two-handed manual alphabet with the left hand as base, and every letter, digit and sign needs ISL review."
)

# The non-dominant left hand is the base: held before the chest, palm to the viewer, fingers apart.
BASE = {"at": "front", "dx": 12, "dy": -24, "shape": "OPEN", "roll": 1, "angle": -30}


def base(**over):
    return {**BASE, **over}


def r(at, shape="POINT", touch="tip", roll=0, angle=-70, **extra):
    return {"at": at, "shape": shape, "touch": touch, "roll": roll, "angle": angle, **extra}


def held(right, left=None, hold=0.35, face=None):
    """One still handshape: reach it, then hold it long enough to read."""
    left = left or base()
    first = {"t": 0.0, "R": right, "L": left}
    if face:
        first["face"] = face
    return [first, {"t": hold, "R": right, "L": left}]


def moving(frames, left=None, step=0.25, face=None):
    """A handshape that traces a path, one key per frame."""
    left = left or base()
    keys = [{"t": round(i * step, 2), "R": f, "L": left} for i, f in enumerate(frames)]
    if face:
        keys[0]["face"] = face
    return keys


SIDEWAYS = base(shape="FLAT", roll=0, angle=-60)
UPRIGHT_INDEX = base(shape="POINT", roll=0, angle=-15)
FLAT_PALM = base(shape="FLAT")

LETTERS = {
    # Vowels point at the base hand's fingertips, thumb to little finger.
    "a": held(r("thumb_opp")),
    "e": held(r("index_opp")),
    "i": held(r("middle_opp")),
    "o": held(r("ring_opp")),
    "u": held(r("pinky_opp")),
    "b": held(r("palm_opp", "CUP", "palm", roll=-1, angle=-80), base(shape="CUP", roll=1, angle=-40)),
    "c": held(r("front", "CUP", "wrist", roll=0, angle=-20, dx=6, dy=-34), {"at": "rest"}),
    "d": held(r("index_opp", "PINCH", "thumb", roll=0, angle=-90, dy=10), UPRIGHT_INDEX),
    "f": held(r("palm_opp", "TWO", "tip", roll=-1, angle=-100), base(shape="TWO", roll=-1, angle=-70)),
    "g": held(r("palm_opp", "FIST", "palm", roll=0, angle=-10, dy=-16), base(shape="FIST", roll=0, angle=-10)),
    "h": moving([r("palm_opp", "FLAT", "palm", roll=-1, angle=-30, dy=-8), r("palm_opp", "FLAT", "palm", roll=-1, angle=-30, dy=8)], FLAT_PALM),
    "j": moving([r("palm_opp", dy=-8), r("palm_opp", dy=4), r("palm_opp", dy=6, dx=6)], FLAT_PALM, step=0.2),
    "k": held(r("index_opp", angle=-90, dy=8), UPRIGHT_INDEX),
    "l": held(r("palm_opp"), FLAT_PALM),
    "m": held(r("palm_opp", "THREE", roll=-1, angle=-80), FLAT_PALM),
    "n": held(r("palm_opp", "TWO", roll=-1, angle=-80), FLAT_PALM),
    "p": held(r("index_opp", "PINCH", "thumb", roll=0, angle=-80), UPRIGHT_INDEX),
    "q": held(r("index_opp", "PINCH", "thumb", roll=0, angle=160, dy=14), UPRIGHT_INDEX),
    "r": held(r("palm_opp", "HOOK", roll=0, angle=-80), FLAT_PALM),
    "s": held(r("pinky_opp", "PINKY", "palm", roll=0, angle=-100), base(shape="PINKY", roll=0, angle=-80)),
    "t": held(r("palm_opp", angle=-90, dy=10), SIDEWAYS),
    "v": held(r("palm_opp", "TWO", roll=-1, angle=-90), FLAT_PALM),
    "w": held(r("palm_opp", "OPEN", "palm", roll=-1, angle=40, dy=-8), base(roll=-1, angle=-50)),
    "x": held(r("index_opp", angle=-45, dy=6), base(shape="POINT", roll=0, angle=-45)),
    "y": held(r("thumb_opp", dy=6), FLAT_PALM),
    "z": moving(
        [r("front", "POINT", "tip", 1, 0, dx=10, dy=-50), r("front", "POINT", "tip", 1, 0, dx=-8, dy=-50),
         r("front", "POINT", "tip", 1, 0, dx=10, dy=-30), r("front", "POINT", "tip", 1, 0, dx=-8, dy=-30)],
        {"at": "rest"}, step=0.2,
    ),
}

# Numbers are held up beside the face; six to nine add a full left hand for five.
COUNT = ["CUP", "POINT", "TWO", "THREE", "FOUR", "OPEN"]
UP = {"at": "shoulder", "dx": 8, "dy": -40, "elbow": "down", "roll": 1, "angle": 0, "touch": "wrist"}
FIVE_LEFT = {**UP, "shape": "OPEN"}
DIGITS = {
    str(n): held({**UP, "shape": COUNT[n] if n <= 5 else COUNT[n - 5]}, {"at": "rest"} if n <= 5 else FIVE_LEFT, hold=0.5)
    for n in range(10)
}

CHEST = {"at": "chest", "touch": "palm", "shape": "FLAT", "roll": -1, "angle": -80}
SIGNS = {
    "thanks": moving([r("chin", "FLAT", "tip", roll=1, angle=0), r("chin", "FLAT", "tip", roll=1, angle=30, dx=10, dy=26)], {"at": "rest"}, step=0.45, face="smile"),
    "bad": held({**UP, "shape": "PINKY", "dy": -30}, {"at": "rest"}, hold=0.6, face="concern"),
    "doctor": held(r("wrist_opp", "TWO", angle=-90, dy=-2), base(shape="FLAT", roll=-1, angle=-80), hold=0.7),
    "help": moving([r("palm_opp", "THUMB", "wrist", roll=0, angle=0, dy=-4), r("palm_opp", "THUMB", "wrist", roll=0, angle=0, dy=-4)],
                   base(shape="FLAT", roll=-1, angle=-90, dy=-6), step=0.5, face="gentle"),
    "come": moving([r("front", "FLAT", "wrist", roll=-1, angle=80, dx=20, dy=-24), r("front", "CUP", "wrist", roll=-1, angle=80, dx=16, dy=-22),
                    r("front", "FLAT", "wrist", roll=-1, angle=80, dx=20, dy=-24), r("front", "CUP", "wrist", roll=-1, angle=80, dx=16, dy=-22)],
                   {"at": "rest"}, step=0.25, face="smile"),
    "go": moving([r("front", "FLAT", "wrist", roll=0, angle=0, dx=0, dy=-24), r("front", "FLAT", "wrist", roll=0, angle=70, dx=34, dy=-30)], {"at": "rest"}, step=0.45),
    "stop": held(r("shoulder", "FLAT", "wrist", roll=1, angle=0, dx=6, dy=-36, elbow="down"), {"at": "rest"}, hold=0.7, face="neutral"),
    "finish": moving([r("front", "FLAT", "wrist", roll=1, angle=-20, dx=-4, dy=-30), r("front", "FLAT", "wrist", roll=-1, angle=60, dx=26, dy=-24)],
                     base(shape="FLAT", roll=1, angle=-20, dx=-4, dy=-30), step=0.45),
    "child": held(r("side", "FLAT", "palm", roll=-1, angle=90, dx=18, dy=-6), {"at": "rest"}, hold=0.7, face="smile"),
    "sit": moving([r("front", "FLAT", "palm", roll=-1, angle=90, dx=10, dy=-30), r("front", "FLAT", "palm", roll=-1, angle=90, dx=10, dy=-6)], {"at": "rest"}, step=0.5),
    "sorry": held(r("ear", "PINCH", "thumb", roll=0, angle=0), {"at": "ear", "shape": "PINCH", "touch": "thumb", "roll": 0, "angle": 0}, hold=0.8, face="gentle"),
    "hit": moving([r("palm_opp", "FIST", "wrist", roll=0, angle=0, dy=-26), r("palm_opp", "FIST", "wrist", roll=0, angle=0, dy=-4)],
                  base(shape="FLAT", roll=-1, angle=-90, dy=-6), step=0.3, face="concern"),
    "time": held(r("wrist_opp", angle=-90), base(shape="FIST", roll=-1, angle=-80), hold=0.6, face="ask"),
    "cry": moving([r("eye", angle=0, roll=1), r("eye", angle=0, roll=1, dy=16)], {"at": "rest"}, step=0.5, face="concern"),
    "see": moving([r("eye", "TWO", "wrist", roll=-1, angle=0, dy=10), r("eye", "TWO", "wrist", roll=-1, angle=40, dx=12, dy=22)], {"at": "rest"}, step=0.45),
    "know": held(r("temple", angle=-30), {"at": "rest"}, hold=0.6),
    "wait": moving([r("front", "FLAT", "palm", roll=-1, angle=90, dx=16, dy=-20), r("front", "FLAT", "palm", roll=-1, angle=90, dx=16, dy=-12),
                    r("front", "FLAT", "palm", roll=-1, angle=90, dx=16, dy=-20)], {"at": "rest"}, step=0.3, face="gentle"),
}


def main() -> None:
    made = (
        [{"id": f"letter.{k}", "keys": v} for k, v in LETTERS.items()]
        + [{"id": f"digit.{k}", "keys": v} for k, v in DIGITS.items()]
        + [{"id": f"sign.{k}", "keys": v} for k, v in SIGNS.items()]
    )
    lines = ",\n".join("  " + json.dumps(g, ensure_ascii=False) for g in made)
    SIGNS_FILE.write_text(f'{{"note": {json.dumps(NOTE)},\n "gestures": [\n{lines}\n]}}\n', encoding="utf-8", newline="\n")
    print(f"signs: {len(made)} entries")


if __name__ == "__main__":
    main()
